package com.trainflow.trainer;
import java.io.*; import java.nio.charset.StandardCharsets; import java.nio.file.*; import java.util.zip.*; import org.apache.pdfbox.Loader; import org.apache.pdfbox.text.PDFTextStripper; import org.springframework.stereotype.Component;
@Component public class CvTextExtractor {public String extract(Path path,String mime)throws IOException{String text;if("application/pdf".equals(mime)){try(var pdf=Loader.loadPDF(path.toFile())){text=new PDFTextStripper().getText(pdf);}}else{text=docx(path);}return text.replace('\u0000',' ').replaceAll("[ \\t]+"," ").trim();}private String docx(Path path)throws IOException{try(var zip=new ZipInputStream(Files.newInputStream(path))){for(ZipEntry e;(e=zip.getNextEntry())!=null;)if("word/document.xml".equals(e.getName())){String xml=new String(zip.readAllBytes(),StandardCharsets.UTF_8);return xml.replaceAll("<w:tab[^>]*/>"," ").replaceAll("</w:p>","\n").replaceAll("<[^>]+>","").replace("&amp;","&").replace("&lt;","<").replace("&gt;",">");}}throw new IOException("DOCX text missing");}}
